INSERT INTO remedies (id, name, condition, condition_label, description, instructions, timing, tracking_note, evidence, caution, premium) VALUES
('cool_compress_itchy_eyes', 'Cool Compress Over Closed Eyes', 'itchy_eyes', 'Itchy Eyes', 'Cold calms the itching and takes down mild puffiness.', 'Rest a clean, cool, damp cloth over closed eyes for 5-10 minutes.', 'As needed, a few times daily.', 'Rate the itch before and after.', 'Cool compresses are a common first-line comfort measure for itchy eyes.', NULL, false),
('no_rubbing_itchy_eyes', 'Do Not Rub - Rinse Instead', 'itchy_eyes', 'Itchy Eyes', 'Rubbing irritates the eye surface and can make itching and swelling worse.', 'Rinse your closed lids with cool clean water, wash hands and face after being outdoors, and change your pillowcase often.', 'Whenever the itch starts.', 'Note what you were doing when the itch began.', 'Avoiding rubbing is standard advice for itchy, irritated eyes.', NULL, true),
('reduce_triggers_itchy_eyes', 'Reduce Dust and Pollen Triggers', 'itchy_eyes', 'Itchy Eyes', 'Allergens and dust landing on the eyes are a very common cause of itching.', 'Keep windows closed on high-pollen days, wash bedding weekly in hot water, wear sunglasses outdoors and remove eye makeup every night.', 'Ongoing.', 'Track itching against pollen levels and cleaning days.', 'Limiting allergen exposure is a core part of managing itchy eyes.', 'Eye pain, vision changes, light sensitivity, discharge or lasting redness need an eye doctor. If you wear contact lenses, stop wearing them until it settles.', true),
('dry_feet_athletes_foot', 'Dry Thoroughly Between Your Toes', 'athletes_foot', 'Athlete''s Foot (Itchy, Peeling Feet)', 'The fungus behind athlete''s foot thrives in damp skin, so staying dry is the most important step.', 'After washing, dry between each toe completely with a clean towel, and use that towel only for your feet.', 'Daily, after every wash.', 'Note itching and peeling over 1-2 weeks.', 'Keeping feet dry is the cornerstone of managing athlete''s foot.', NULL, false),
('breathable_socks_athletes_foot', 'Breathable Socks and Rotated Shoes', 'athletes_foot', 'Athlete''s Foot (Itchy, Peeling Feet)', 'Sweaty socks and damp shoes keep the fungus going.', 'Wear cotton or moisture-wicking socks, change them daily or when damp, and let shoes dry for 24 hours between wears.', 'Daily.', 'Track whether itching eases with the changes.', 'Reducing moisture around the feet helps prevent athlete''s foot from persisting.', NULL, true),
('shared_spaces_athletes_foot', 'Protect Your Feet in Shared Wet Areas', 'athletes_foot', 'Athlete''s Foot (Itchy, Peeling Feet)', 'Gym floors and communal showers are common places to pick up and spread the fungus.', 'Wear sandals in communal showers and changing rooms, and wash towels and socks in hot water.', 'Whenever using shared spaces, and weekly for laundry.', 'Note whether it spreads to other areas.', 'Avoiding bare feet in damp shared spaces lowers the risk of catching and spreading it.', 'If it is not better after 2 weeks, spreads, cracks and bleeds or looks infected, see a pharmacist or doctor, as you may need an antifungal treatment.', true),
('leave_alone_warts', 'Leave It Alone and Cover It', 'warts', 'Warts', 'Warts are caused by a common virus and often clear on their own, and picking can spread them.', 'Do not pick, scratch or bite the wart. Cover it with a plaster in shared areas and wash your hands after touching it.', 'Ongoing.', 'Photograph it monthly to see if it is shrinking.', 'Most common warts clear by themselves over time, and avoiding picking reduces spread.', NULL, false),
('shower_shoes_warts', 'Keep Feet Dry and Wear Shower Shoes', 'warts', 'Warts', 'Warts on the feet spread easily in damp, shared spaces.', 'Wear sandals in communal showers and pool areas, dry feet well, and keep towels and nail tools separate for the affected area.', 'Ongoing.', 'Note whether new warts appear.', 'Avoiding bare feet in communal wet areas is standard advice to prevent foot warts.', NULL, true),
('patience_track_warts', 'Be Patient and Track Changes', 'warts', 'Warts', 'Warts can take months to go, and harsh home treatments often do more harm than good.', 'Avoid cutting, burning or scraping at home, and check on the wart every few weeks.', 'Monthly check.', 'Note size, colour and any pain.', 'Warts often resolve with time, and aggressive self-treatment risks scarring and infection.', 'See a doctor if a wart bleeds, changes, is very painful, is on your face or genitals, or if you have a weakened immune system.', true),
('leave_intact_blisters', 'Leave the Blister Intact and Cover It', 'friction_blisters', 'Friction Blisters', 'The skin over a blister is a natural sterile cover that protects the tender skin underneath.', 'Clean around it gently and cover with a soft padded plaster. Do not pop it.', 'Daily until it settles.', 'Check size and tenderness each day.', 'Leaving blisters intact is standard first aid guidance because it lowers infection risk.', NULL, false),
('reduce_friction_blisters', 'Reduce Friction at the Source', 'friction_blisters', 'Friction Blisters', 'Blisters come from rubbing, so fixing the cause stops new ones forming.', 'Wear well-fitting shoes and moisture-wicking socks, break in new shoes gradually, and pad or tape known hot spots before long walks.', 'Before walks, runs or new shoes.', 'Note which shoes or activities cause blisters.', 'Reducing friction and moisture is the main way to prevent blisters.', NULL, true),
('clean_if_burst_blisters', 'If It Bursts, Keep It Clean', 'friction_blisters', 'Friction Blisters', 'A burst blister leaves raw skin that can pick up germs.', 'Wash gently with soap and water, leave the flap of skin in place, and cover with a clean dressing changed daily.', 'Daily until healed.', 'Watch for redness, warmth or pus.', 'Gentle cleaning and covering supports healing and lowers infection risk.', 'Spreading redness, pus, fever or red streaks need a doctor. If you have diabetes, get any foot blister checked.', true),
('gentle_stretch_stiff_neck', 'Gentle Neck Movements', 'stiff_neck', 'Stiff Neck', 'Slow, gentle movement keeps tight neck muscles from locking up further.', 'Slowly tilt your ear toward your shoulder and hold for 15-20 seconds on each side, then gently turn to look over each shoulder. Never force the stretch.', 'A few times daily.', 'Rate stiffness and range of movement each morning.', 'Gentle range-of-motion movement is commonly recommended for neck stiffness.', NULL, false),
('warm_compress_stiff_neck', 'Warm Compress or Warm Shower', 'stiff_neck', 'Stiff Neck', 'Heat relaxes tight muscles and eases the aching.', 'Rest a warm pack on the back of your neck for 15-20 minutes, or let warm shower water run over it.', '1-3 times daily.', 'Note stiffness before and after.', 'Heat is a standard comfort measure for muscle-related neck stiffness.', NULL, true),
('sleep_setup_stiff_neck', 'Check Your Pillow and Sleeping Position', 'stiff_neck', 'Stiff Neck', 'Waking with a stiff neck often points to a pillow or position that bends the neck out of line.', 'Use a pillow that keeps your neck level with your spine, avoid sleeping on your stomach, and take breaks from looking down at your phone.', 'Nightly and through the day.', 'Note whether stiffness is worse on waking.', 'Neck alignment during sleep and screen use are common contributors to stiffness.', 'Stiff neck with fever, severe headache, numbness or weakness in the arms, or after an injury needs urgent medical care.', true),
('water_food_caffeine_jitters', 'Drink Water and Eat Something', 'caffeine_jitters', 'Caffeine Jitters', 'Caffeine hits harder on an empty stomach, and food and fluid help steady you.', 'Drink a glass of water and eat something with protein or complex carbohydrates, like eggs on toast or a banana with nuts.', 'When the jitters start.', 'Note how long it takes to settle.', 'Eating and hydrating are commonly suggested to ease the effects of too much caffeine.', NULL, false),
('slow_breathing_caffeine_jitters', 'Slow Breathing and a Gentle Walk', 'caffeine_jitters', 'Caffeine Jitters', 'Calm breathing and light movement help burn off nervous energy.', 'Breathe in for 4 counts and out for 6 for a few minutes, then take a gentle walk.', 'When the jitters start.', 'Rate how shaky you feel before and after.', 'Slow breathing and light activity are well supported ways to calm physical tension.', NULL, true),
('cut_back_caffeine_jitters', 'Cut Back Gradually and Stop Caffeine Earlier', 'caffeine_jitters', 'Caffeine Jitters', 'Smaller amounts, earlier in the day, are easier on your system.', 'Reduce coffee, tea and energy drinks a little each week and avoid caffeine from early afternoon onwards.', 'Daily, ongoing.', 'Track your caffeine drinks and how you feel.', 'Gradual reduction avoids withdrawal headaches and reduces jitteriness.', 'Chest pain, a very rapid or irregular heartbeat, or fainting need medical help.', true),
('daylight_jet_lag', 'Get Daylight at Local Daytime', 'jet_lag', 'Jet Lag', 'Light is the main signal that resets your body clock to a new time zone.', 'Spend time outside in daylight during local daytime, and keep lights low and screens dim in the local evening.', 'Daily for the first few days after arriving.', 'Note when you feel sleepy and alert each day.', 'Light exposure is the strongest cue for resetting the body clock.', NULL, false),
('shift_schedule_jet_lag', 'Shift Sleep and Meals Gradually', 'jet_lag', 'Jet Lag', 'Starting to adjust early and eating on local time helps your body catch up faster.', 'A few days before travel, shift bedtime slightly toward the new time zone, and on arrival eat at local mealtimes.', 'Before and after travel.', 'Log sleep and energy each day.', 'Gradual schedule shifting and mealtimes help the body clock adapt.', NULL, true),
('hydrate_nap_jet_lag', 'Hydrate and Keep Naps Short', 'jet_lag', 'Jet Lag', 'Dehydration and long daytime naps make it harder to settle into the new schedule.', 'Drink water on the flight, go easy on alcohol and caffeine, and limit naps to 20-30 minutes before mid-afternoon.', 'During and after travel.', 'Note how well you sleep the first nights.', 'Hydration and short naps are standard jet lag advice.', 'Sleep problems lasting more than 2 weeks, or calf pain or swelling after a long flight, need medical attention.', true),
('phone_free_window_phone_overuse', 'Set a Phone-Free Window', 'phone_overuse', 'Too Much Phone Time / Doomscrolling', 'Giving yourself protected phone-free time breaks the automatic reach-and-scroll habit.', 'Keep the first 30 minutes after waking and the last hour before bed phone-free, and charge your phone outside the bedroom.', 'Every day.', 'Note your daily screen time for a week.', 'Phone-free periods, especially before bed, are linked to better sleep and mood.', NULL, false),
('less_tempting_phone_overuse', 'Make the Phone Less Tempting', 'phone_overuse', 'Too Much Phone Time / Doomscrolling', 'Colours, notifications and easy access keep you scrolling without deciding to.', 'Turn the screen to grayscale, switch off non-essential notifications, and move the most tempting apps off your home screen.', 'One-time setup, then ongoing.', 'Compare screen time before and after.', 'Reducing cues and notifications lowers compulsive checking.', NULL, true),
('replace_habit_phone_overuse', 'Replace the Habit With Something Else', 'phone_overuse', 'Too Much Phone Time / Doomscrolling', 'It is easier to swap a habit for another than to simply stop it.', 'Pick a go-to alternative for moments you reach for your phone, like a book, a short walk or calling a friend.', 'Whenever you notice the urge.', 'Note how often you pick the alternative.', 'Habit replacement is more effective than relying on willpower alone.', 'If scrolling is crowding out sleep, work or relationships and you cannot cut back, talk to a doctor or counsellor.', true),
('scheduled_calls_homesickness', 'Schedule Regular Calls Home', 'homesickness', 'Homesickness', 'Predictable contact gives you something to look forward to without keeping you stuck in longing.', 'Set specific times to call or video chat with family and friends, rather than checking in constantly.', 'A few set times each week.', 'Notice how you feel before and after calls.', 'Regular, structured contact with loved ones is a common coping strategy for homesickness.', NULL, false),
('familiar_routines_homesickness', 'Build Familiar Routines and Bring Comforts From Home', 'homesickness', 'Homesickness', 'Familiar foods, sounds and routines make a new place feel safer.', 'Keep a regular daily routine, cook familiar meals, and surround yourself with photos, music or objects from home.', 'Daily.', 'Note how settled you feel across the week.', 'Familiar routines and comforts help ease the stress of a new environment.', NULL, true),
('small_steps_homesickness', 'Explore and Connect Locally in Small Steps', 'homesickness', 'Homesickness', 'Building a little life where you are gradually makes the new place feel like yours.', 'Plan one small outing or group activity a few times a week, like a class, a walk or a coffee with someone new.', 'A few times weekly.', 'Note things you enjoyed about where you are.', 'Gradual engagement with a new environment reduces homesickness over time.', 'If low mood is constant, interferes with daily life or you feel hopeless, talk to a doctor or counsellor.', true),
('two_minute_start_motivation', 'Start With a Two-Minute Version', 'low_motivation', 'Low Motivation', 'Getting started is usually the hardest part, and momentum often carries you on once you begin.', 'Tell yourself you will only do the task for 2 minutes, then stop or keep going if you feel like it.', 'Whenever you are stuck.', 'Note how often 2 minutes turns into more.', 'Starting small is a well-known way to overcome the inertia of low motivation.', NULL, false),
('one_small_goal_motivation', 'Pick One Small Goal for Today', 'low_motivation', 'Low Motivation', 'A single clear goal feels doable, and finishing it builds a sense of progress.', 'Each morning, write down one small thing you will finish today and do that before anything else.', 'Every morning.', 'Tick off your goal each evening.', 'Small, specific goals are more motivating than large vague ones.', NULL, true),
('move_daylight_fuel_motivation', 'Move, Get Daylight and Eat Regularly', 'low_motivation', 'Low Motivation', 'Low energy, little light and skipped meals all drag motivation down.', 'Take a short walk outside, eat regular meals, and keep a steady sleep schedule.', 'Daily.', 'Note energy and motivation each evening.', 'Light, movement, food and sleep all strongly influence energy and drive.', 'Loss of motivation or interest lasting more than 2 weeks, especially with low mood, is worth talking to a doctor about.', true),
('write_it_down_forgetfulness', 'Write It Down and Use One Reminder System', 'forgetfulness', 'Forgetfulness', 'Forgetting often comes from trying to hold too much in your head at once.', 'Pick one notebook or phone list for everything, and keep keys, wallet and phone in the same spot.', 'Daily.', 'Note how often you misplace or forget things.', 'External reminders are a proven way to reduce everyday memory slips.', NULL, false),
('protect_sleep_forgetfulness', 'Protect Your Sleep', 'forgetfulness', 'Forgetfulness', 'Memory is consolidated during sleep, so poor sleep makes forgetting more likely.', 'Keep a consistent bedtime and wake time, and wind down away from screens.', 'Nightly.', 'Compare forgetfulness after nights of good and poor sleep.', 'Sleep plays a key role in forming and storing memories.', NULL, true),
('one_thing_forgetfulness', 'Do One Thing at a Time and Say It Aloud', 'forgetfulness', 'Forgetfulness', 'Many memory lapses are really attention lapses, because the information never fully registered.', 'Pause and focus on what you are doing, and say aloud where you put things or what you have agreed to do.', 'Throughout the day.', 'Note whether lapses drop when you slow down.', 'Focused attention and verbal repetition improve how well information is stored.', 'Memory problems that are sudden, getting worse or affecting daily life need a doctor.', true),
('let_it_out_crying', 'Let the Tears Come, Then Settle', 'crying_spells', 'Crying Easily or Crying Spells', 'Crying is a natural way for the body to release emotion, and many people feel calmer afterwards.', 'Find a private spot and let it happen, then sip water, splash your face with cool water and breathe slowly.', 'Whenever it happens.', 'Note how you feel 10 minutes afterwards.', 'Crying can be a healthy release, and calming steps afterwards help the body settle.', NULL, false),
('name_feeling_crying', 'Name What You Are Feeling or Write It Out', 'crying_spells', 'Crying Easily or Crying Spells', 'Putting words to feelings can ease their intensity and show you what is going on.', 'Jot down ''Right now I feel...'' without judging what comes out, and re-read it later.', 'When you feel overwhelmed.', 'Notice patterns in what you write over a week or two.', 'Expressive writing is linked to improved emotional processing.', NULL, true),
('basics_reach_out_crying', 'Cover the Basics and Reach Out', 'crying_spells', 'Crying Easily or Crying Spells', 'Poor sleep, hunger and being alone with a feeling all make emotions harder to handle.', 'Make sure you are eating, resting and getting some movement, and talk to someone you trust about how you are doing.', 'Daily.', 'Note sleep, meals and mood alongside how often you cry.', 'Sleep, food and social support all affect emotional resilience.', 'If crying is frequent, feels out of your control, or comes with hopelessness or thoughts of harming yourself, please speak to a doctor or counsellor, or someone you trust, soon.', true),
('slow_breathing_racing_heart', 'Slow, Steady Breathing', 'racing_heart', 'Racing Heart (Stress-Related)', 'Slow breathing activates the body''s calming response and helps bring your heart rate down.', 'Sit down and breathe in through your nose for 4 counts and out slowly for 6, for several minutes.', 'When it happens.', 'Note how long it takes to settle.', 'Slow breathing is a well-supported way to calm stress-related heart racing.', 'Racing heart with chest pain, fainting, shortness of breath or dizziness needs urgent medical care.', false),
('cut_stimulants_racing_heart', 'Cut Back on Caffeine and Stimulants', 'racing_heart', 'Racing Heart (Stress-Related)', 'Coffee, strong tea, energy drinks and nicotine can all make your heart race.', 'Reduce stimulants gradually and avoid them when you feel anxious or have not slept well.', 'Daily.', 'Note whether episodes follow stimulants.', 'Stimulants are a very common trigger of a racing heart.', NULL, true),
('log_pattern_racing_heart', 'Note When It Happens', 'racing_heart', 'Racing Heart (Stress-Related)', 'Patterns in timing and triggers help you and a doctor understand what is going on.', 'Write down the time, what you were doing, what you had eaten or drunk, and how stressed you felt.', 'Each time it happens.', 'Review your notes after a couple of weeks.', 'Symptom diaries help identify triggers and are useful to share with a doctor.', 'Recurring episodes should be checked by a doctor.', true),
('cool_calm_razor_burn', 'Cool, Calm and Moisturize', 'razor_burn', 'Razor Burn', 'Cooling the skin reduces the sting, and moisture helps the irritated surface recover.', 'Hold a cool damp cloth on the area, then apply pure aloe vera gel or a fragrance-free moisturizer.', 'After shaving and as needed.', 'Rate redness and stinging each day.', 'Cooling and moisturizing are standard soothing steps for razor burn.', NULL, false),
('shave_smarter_razor_burn', 'Shave Smarter', 'razor_burn', 'Razor Burn', 'Dry shaving, dull blades and too much pressure are the main causes of razor burn.', 'Soften skin with warm water first, use shaving cream, shave in the direction of hair growth with light pressure, and use a fresh sharp razor.', 'Every time you shave.', 'Note whether burn drops with the new technique.', 'Good shaving technique greatly reduces irritation.', NULL, true),
('rest_skin_razor_burn', 'Give Skin a Break and Avoid Irritants', 'razor_burn', 'Razor Burn', 'Shaving over irritated skin keeps the burn going.', 'Skip shaving until skin has calmed, and avoid scented products and tight clothing on the area.', 'Until skin has settled.', 'Photograph the area every few days.', 'Resting irritated skin allows it to heal.', 'Pus, spreading redness or increasing pain need a doctor.', true),
('moisturize_after_washing_dry_hands', 'Moisturize Right After Washing', 'dry_hands', 'Dry, Cracked Hands', 'Moisturizer seals in water while skin is still slightly damp.', 'Apply a thick cream or ointment right after washing, and keep a small tube where you will use it.', 'After every hand wash.', 'Rate dryness and cracking each evening.', 'Frequent moisturizing is the main treatment for dry hands.', NULL, false),
('gloves_mild_soap_dry_hands', 'Wear Gloves and Use Mild Soap', 'dry_hands', 'Dry, Cracked Hands', 'Water, cleaning products and cold air strip the skin''s natural oils.', 'Wear rubber gloves for washing up and cleaning, warm gloves outside, and use mild soap with lukewarm water.', 'Daily.', 'Note flare-ups against chores and weather.', 'Protecting hands from irritants and cold helps skin recover.', NULL, true),
('overnight_mask_dry_hands', 'Overnight Hand Mask', 'dry_hands', 'Dry, Cracked Hands', 'A thick layer overnight gives skin hours to repair without being washed off.', 'Smooth petroleum jelly or a heavy balm over your hands before bed and put on soft cotton gloves.', 'A few nights a week or nightly in bad flares.', 'Compare how hands feel in the morning.', 'Occlusive moisturizers are very effective for severely dry skin.', 'Cracks that bleed, look infected or a rash that does not improve in 2 weeks need a doctor.', true),
('warm_soak_ingrown_toenail', 'Warm Soaks', 'ingrown_toenail', 'Ingrown Toenail', 'Warm water softens the skin around the nail and eases tenderness.', 'Soak the foot in warm water for 15-20 minutes, then dry thoroughly.', '3-4 times daily.', 'Rate pain and redness each day.', 'Warm soaks are a standard first step for mild ingrown toenails.', NULL, false),
('roomy_shoes_ingrown_toenail', 'Wear Roomy or Open Footwear', 'ingrown_toenail', 'Ingrown Toenail', 'Tight shoes press the nail edge into the skin and keep it irritated.', 'Choose shoes with a roomy toe box or open sandals while it heals.', 'Until it heals.', 'Note whether pain eases in looser shoes.', 'Reducing pressure on the toe supports healing.', NULL, true),
('trim_straight_ingrown_toenail', 'Trim Straight Across and Do Not Dig', 'ingrown_toenail', 'Ingrown Toenail', 'Rounded cuts and digging at the corner encourage the nail to grow into the skin.', 'Cut nails straight across, not too short, and do not dig at the corner.', 'Every time you trim.', 'Check the nail edge weekly.', 'Straight trimming is the standard way to prevent ingrown toenails.', 'Increasing pain, redness, swelling or pus needs a doctor, and anyone with diabetes should get it checked early.', true),
('change_often_pad_irritation', 'Change Pads Regularly', 'pad_irritation', 'Irritation From Pads', 'Moisture trapped against the skin is the main cause of irritation and rash.', 'Change pads every few hours, even on lighter days, and keep the area clean and dry.', 'Through your period.', 'Note soreness each day of your period.', 'Frequent changing reduces moisture and friction against the skin.', NULL, false),
('unscented_breathable_pad_irritation', 'Choose Unscented, Breathable Options', 'pad_irritation', 'Irritation From Pads', 'Fragrances and plastic-type layers can irritate delicate skin.', 'Use unscented pads made with breathable materials, avoid scented liners, and consider other period products if pads keep irritating.', 'Every period.', 'Compare irritation across different products.', 'Fragrance-free, breathable products are less likely to cause irritation.', NULL, true),
('gentle_care_pad_irritation', 'Wash Gently and Protect the Skin', 'pad_irritation', 'Irritation From Pads', 'Harsh soap makes irritated skin worse, while a barrier helps it recover.', 'Wash the outer area with warm water only, pat dry, and apply a thin layer of petroleum jelly to the irritated outer skin.', 'Daily during irritation.', 'Photograph or note redness every day or two.', 'Gentle washing and barrier protection are standard care for irritated skin.', 'Irritation that does not improve in a few days, spreads or comes with unusual discharge needs a doctor.', true),
('scalp_massage_slow_hair_growth', 'Daily Scalp Massage', 'slow_hair_growth', 'Slow Hair Growth', 'Massage increases blood flow to the scalp, which may support healthier hair over time.', 'Use your fingertips to massage your scalp in small circles for 4-5 minutes.', 'Daily.', 'Take a monthly photo of your hairline and parting.', 'Small studies suggest scalp massage may support thicker hair, though evidence is modest.', NULL, false),
('protein_iron_slow_hair_growth', 'Eat Enough Protein, Iron and Zinc-Rich Foods', 'slow_hair_growth', 'Slow Hair Growth', 'Hair is made of protein and needs a steady supply of nutrients to grow.', 'Include eggs, beans, fish, leafy greens, nuts and seeds in your meals.', 'Daily, ongoing.', 'Track hair length and strength over a few months.', 'Adequate protein, iron and zinc are important for normal hair growth.', NULL, true),
('gentle_handling_slow_hair_growth', 'Gentle Handling and Regular Trims', 'slow_hair_growth', 'Slow Hair Growth', 'Breakage makes hair look like it is not growing, even when it is.', 'Avoid tight styles and rough brushing, use a wide-toothed comb on damp hair, and trim split ends regularly.', 'Ongoing.', 'Measure length every couple of months.', 'Reducing breakage helps hair retain its length.', 'Sudden shedding or patches of hair loss need a doctor.', true),
('daily_sunscreen_fine_lines', 'Daily Sun Protection', 'fine_lines', 'Fine Lines and Early Wrinkles', 'Sun exposure is the biggest driver of fine lines and early wrinkles.', 'Apply sunscreen to your face, neck and hands every morning, and wear a hat in strong sun.', 'Every morning.', 'Take a photo every few months to compare.', 'Daily sunscreen is the most consistently recommended way to slow skin aging.', NULL, false),
('moisturize_hydrate_fine_lines', 'Moisturize Daily and Stay Hydrated', 'fine_lines', 'Fine Lines and Early Wrinkles', 'Dry skin makes fine lines more noticeable, while moisturized skin looks smoother.', 'Apply moisturizer morning and night and drink water through the day.', 'Morning and night.', 'Note how lines look when skin is well moisturized.', 'Moisturizing temporarily plumps skin and softens the look of fine lines.', NULL, true),
('sleep_lifestyle_fine_lines', 'Protect Your Skin Through Sleep and Lifestyle', 'fine_lines', 'Fine Lines and Early Wrinkles', 'Sleep, smoking and diet all show up in your skin over time.', 'Aim for regular sleep, avoid smoking, and eat plenty of colourful fruit and vegetables.', 'Ongoing.', 'Note changes in skin quality over months.', 'Sleep, not smoking and a nutrient-rich diet are linked to healthier-looking skin.', 'Any new or changing skin spot should be checked by a doctor.', true),
('stop_more_sun_suntan', 'Stop Further Tanning', 'suntan', 'Suntan', 'More sun keeps darkening the skin, so protection comes first.', 'Stay in the shade at midday, wear sunscreen and cover up with clothing and a hat.', 'Daily.', 'Take a photo weekly to track fading.', 'Avoiding more sun exposure is essential for a tan to fade.', NULL, false),
('yoghurt_aloe_mask_suntan', 'Plain Yoghurt or Aloe Mask', 'suntan', 'Suntan', 'Both are soothing, and yoghurt contains mild lactic acid that gently lifts surface pigment.', 'Apply plain yoghurt or aloe vera gel to tanned skin for 15 minutes, then rinse with cool water. Patch test first.', '2-3 times a week.', 'Compare skin tone over a few weeks.', 'Mild lactic acid and soothing gels are commonly used for gentle skin brightening.', 'Stop if skin stings or turns red.', true),
('gentle_exfoliate_suntan', 'Gentle Exfoliation and Moisturizer', 'suntan', 'Suntan', 'Tanned skin cells shed as skin renews, and gentle exfoliation helps it along.', 'Once a week, gently exfoliate with a soft cloth or mild scrub, then moisturize well.', 'Once a week.', 'Note how the tan is fading.', 'Gentle exfoliation supports natural skin renewal.', 'Blistering sunburn needs medical care, and any new or changing mole should be checked by a doctor.', true),
('lip_balm_spf_dark_lips', 'Lip Balm With Sun Protection', 'dark_lips', 'Dark Lips', 'Sun exposure darkens lip skin, and protection helps stop it getting worse.', 'Apply a lip balm with SPF every morning and reapply when outdoors.', 'Daily.', 'Take a monthly photo to track colour.', 'Sun protection is important for preventing and lightening lip darkening.', NULL, false),
('gentle_scrub_dark_lips', 'Gentle Weekly Exfoliation', 'dark_lips', 'Dark Lips', 'Removing dead surface skin can improve how even lip colour looks.', 'Mix a little sugar with honey or oil and gently rub over the lips for 30 seconds, rinse, then apply balm.', 'Once a week.', 'Compare colour and smoothness.', 'Gentle exfoliation helps remove dull surface skin.', NULL, true),
('habits_hydration_dark_lips', 'Stay Hydrated and Avoid Licking, Biting and Smoking', 'dark_lips', 'Dark Lips', 'Irritation and smoking darken and dry the lips.', 'Drink water regularly, avoid licking and biting your lips, and avoid smoking.', 'Ongoing.', 'Note changes alongside your habits.', 'Reducing irritation and avoiding smoking supports even lip colour.', 'Sudden dark patches, or a spot on the lip that changes or does not heal, should be seen by a doctor.', true),
('moisturize_dark_knees', 'Moisturize Daily', 'dark_knees_elbows', 'Dark Knees and Elbows', 'Dry, thickened skin on elbows and knees looks darker, and moisture helps soften it.', 'Apply a thick moisturizer to elbows and knees twice a day, especially after bathing.', 'Morning and night.', 'Take a monthly photo.', 'Regular moisturizing is the first step for rough, darkened skin on these areas.', NULL, false),
('gentle_exfoliate_dark_knees', 'Gentle Exfoliation Once or Twice a Week', 'dark_knees_elbows', 'Dark Knees and Elbows', 'Dead skin builds up on these areas and adds to the dark look.', 'Gently exfoliate with a soft cloth or mild scrub, then moisturize. Do not scrub hard.', '1-2 times a week.', 'Compare skin texture over a month.', 'Gentle exfoliation helps remove built-up dead skin.', NULL, true),
('reduce_friction_dark_knees', 'Reduce Friction and Pressure', 'dark_knees_elbows', 'Dark Knees and Elbows', 'Constant rubbing and leaning darken and thicken the skin over time.', 'Avoid resting your weight on elbows, kneel on a cushion, and protect the skin from sun.', 'Ongoing.', 'Note whether darkening slows down.', 'Reducing friction and pressure limits ongoing darkening.', 'Dark, thick, velvety patches that spread, especially on the neck, underarms or groin, should be checked by a doctor.', true),
('breath_hold_hiccups', 'Hold Your Breath, Then Breathe Out Slowly', 'hiccups', 'Hiccups', 'Holding your breath raises carbon dioxide levels, which can calm the muscle spasm behind hiccups.', 'Take a breath, hold it for about 10 seconds, then breathe out slowly. Repeat a few times.', 'When hiccups start.', 'Note whether they stop.', 'Breath-holding is a widely used home technique for hiccups.', NULL, false),
('sip_water_hiccups', 'Sip Cold Water Slowly', 'hiccups', 'Hiccups', 'Steady swallowing can reset the nerves involved in hiccups.', 'Take small, slow sips of cold water, or swallow a small spoonful of sugar.', 'When hiccups start.', 'Note how long they last.', 'Swallowing-based tricks are commonly used and often work for short bouts.', NULL, true),
('eat_slowly_hiccups', 'Eat and Drink Slowly and Avoid Triggers', 'hiccups', 'Hiccups', 'Big meals, fizzy drinks and alcohol are common triggers.', 'Eat in smaller portions, chew slowly, and go easy on fizzy drinks and alcohol.', 'At meals.', 'Note what you had before hiccups started.', 'Eating quickly and fizzy drinks are well-known triggers.', 'Hiccups lasting more than 48 hours, or interfering with eating or sleeping, need a doctor.', true),
('notice_triggers_nail_biting', 'Notice When and Why You Bite', 'nail_biting', 'Nail Biting', 'Biting is often automatic, so spotting the trigger is the first step to changing it.', 'For a week, note when you bite, such as boredom, stress or screen time.', 'Daily for a week.', 'Write down times and triggers.', 'Awareness training is a core part of habit change.', NULL, false),
('busy_hands_nail_biting', 'Keep Your Hands Busy', 'nail_biting', 'Nail Biting', 'Giving your hands something else to do replaces the biting habit.', 'Keep a fidget toy or stress ball handy, and keep nails short and neat so there is less to bite.', 'Whenever you feel the urge.', 'Note how often you catch yourself.', 'Substituting another action is a standard habit-reversal technique.', NULL, true),
('make_it_harder_nail_biting', 'Make Biting Unpleasant or Harder', 'nail_biting', 'Nail Biting', 'A physical barrier or bitter taste interrupts the automatic habit.', 'Use a bitter-tasting nail polish, or cover bitten fingertips with plasters.', 'Daily until the habit fades.', 'Compare nail length after a few weeks.', 'Taste aversion and barriers are commonly used to interrupt nail biting.', 'Bitten skin that bleeds or looks infected needs care, and if biting feels uncontrollable or distressing, talk to a doctor.', true),
('rinse_after_stained_teeth', 'Rinse After Staining Foods and Drinks', 'stained_teeth', 'Stained or Yellow Teeth', 'Coffee, tea, red wine and dark sauces leave pigment that builds up on teeth.', 'Swish water around your mouth after staining drinks and foods, and wait 30 minutes before brushing after anything acidic.', 'After meals and drinks.', 'Take a photo of your teeth monthly.', 'Rinsing reduces how much pigment stays on tooth surfaces.', NULL, false),
('limit_stains_stained_teeth', 'Cut Back on Stain Culprits', 'stained_teeth', 'Stained or Yellow Teeth', 'Reducing what stains teeth lets natural colour show through.', 'Use a straw for dark drinks, limit coffee, tea and red wine, and avoid smoking.', 'Ongoing.', 'Compare tooth shade over a few months.', 'Smoking and dark drinks are the most common causes of tooth staining.', NULL, true),
('brush_clean_stained_teeth', 'Brush Gently Twice Daily and Get Regular Cleans', 'stained_teeth', 'Stained or Yellow Teeth', 'Daily brushing prevents build-up, and professional cleaning removes surface stains brushing cannot.', 'Brush twice a day with a soft brush, and see a dentist or hygienist for regular cleans.', 'Twice daily, plus regular dental visits.', 'Note any change after a professional clean.', 'Regular brushing and professional cleaning are the standard approach to surface stains.', 'Avoid lemon or baking soda scrubs, which can wear enamel. A single dark tooth, or sudden yellowing or greying, should be seen by a dentist.', true);
